"""Render rows of strings as a GitHub markdown table."""


def _cell(s):
    return s.strip().replace("|", "\\|")


def to_markdown(rows):
    if not rows:
        raise ValueError("no rows")
    width = len(rows[0])
    if width == 0:
        raise ValueError("header has no cells")
    for i, row in enumerate(rows[1:], start=2):
        if len(row) != width:
            raise ValueError(f"row {i} has {len(row)} cells, expected {width}")
    lines = [list(rows[0]), ["---"] * width] + [list(r) for r in rows[1:]]
    out = []
    for n, line in enumerate(lines):
        cells = line if n == 1 else [_cell(c) for c in line]
        out.append("| " + " | ".join(cells) + " |")
    return "\n".join(out)
